def fizzbuzz(n):
    resultado = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            resultado.append("FizzBuzz")
        elif i % 3 == 0:
            resultado.append("Fizz")
        elif i % 5 == 0:
            resultado.append("Buzz")
        else:
            resultado.append(str(i))
    return resultado

def parsear_duracion(s):
    minutos = 0
    for caracter in s:
        if caracter == 'h':
            minutos += int(s[:s.index(caracter)]) * 60
        elif caracter == 'm':
            minutos += int(s[:s.index(caracter)])
    return minutos

def es_palindromo(s):
    s_limpio = ''.join(char.lower() for char in s if char.isalnum())
    return s_limpio == s_limpio[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    izq = 0
    der = len(lista) - 1
    while izq <= der:
        mid = (izq + der) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            izq = mid + 1
        else:
            der = mid - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item.get(clave)
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

import re
from collections import Counter

def contar_palabras(texto):
    texto = texto.lower()
    palabras = re.findall(r'\b\w+\b', texto)
    return dict(Counter(palabras))

def rotar(lista, n):
    if not lista:
        return []

    n = n % len(lista)
    if n < 0:
        n += len(lista)

    return lista[-n:] + lista[:-n]

def desde_romano(s):
    valores = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    resultado = 0
    anterior = 0
    for letra in s.upper():
        valor = valores[letra]
        if valor < anterior:
            resultado -= valor
        else:
            resultado += valor
        anterior = valor
    return resultado

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = (lista[0], 1)
    actual_elemento = lista[0]
    actual_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == actual_elemento:
            actual_racha += 1
        else:
            if actual_racha > max_racha[1]:
                max_racha = (actual_elemento, actual_racha)
            actual_elemento = lista[i]
            actual_racha = 1

    # Verificar la última racha
    if actual_racha > max_racha[1]:
        max_racha = (actual_elemento, actual_racha)

    return max_racha

def a_camel(s):
    parts = s.split('_')
    return parts[0].lower() + ''.join(word.capitalize() for word in parts[1:])

def a_snake(s):
    if not s:
        return s
    result = ""
    for i, char in enumerate(s):
        if char.isupper():
            if i == 0:
                result += char.lower()
            else:
                result += "_" + char.lower()
        else:
            result += char
    return result

def primos(n):
    if n < 2:
        return []

    primos = [2]
    for num in range(3, n + 1, 2):
        is_prime = True
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primos.append(num)
    return primos

def mcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    intervalos.sort(key=lambda x: x[0])

    fusionados = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        ultimo_inicio, ultimo_fin = fusionados[-1]
        if inicio <= ultimo_fin:
            ultimo_fin = max(ultimo_fin, fin)
            fusionados[-1] = (ultimo_inicio, ultimo_fin)
        else:
            fusionados.append((inicio, fin))

    return fusionados

def es_anagrama(a, b):
    a = a.lower().replace(" ", "")
    b = b.lower().replace(" ", "")
    return sorted(a) == sorted(b)

def comprimir(s):
    if not s:
        return s

    contadores = {}
    for char in s:
        contadores[char] = contadores.get(char, 0) + 1

    comprimido = ""
    for char, count in contadores.items():
        comprimido += f"{char}{count}"

    return comprimido if len(comprimido) < len(s) else s

def balanceado(s):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for char in s:
        if char in mapping:
            top = stack.pop() if stack else None
            if top != mapping[char]:
                return False
        elif char in '({[':
            stack.append(char)
    return not stack

def transpuesta(m):
    if not m or not m[0]:
        return []
    filas = len(m)
    columnas = len(m[0])
    return [[m[i][j] for i in range(filas)] for j in range(columnas)]

def raiz_digital(n):
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def sin_duplicados(lista):
    seen = set()
    resultado = []
    for elemento in lista:
        if elemento not in seen:
            seen.add(elemento)
            resultado.append(elemento)
    return resultado

def formatear_bytes(n):
    if n < 1024:
        return f"{n} B"
    elif n < 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    elif n < 1024 * 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB"
    else:
        return f"{n / (1024 * 1024 * 1024):.1f} GB"

def en_lotes(lista, tamano):
    if not lista:
        return []
    return [lista[i:i + tamano] for i in range(0, len(lista), tamano)]
